// Domain Layer - Port Interface
// File: src/domain/ports/IPaymentGateway.ts

export interface IPaymentGateway {
  /**
   * Processes a payment transaction
   * @param amount - The payment amount in cents
   * @param currency - The currency code (e.g., 'usd')
   * @param paymentMethodId - The payment method identifier
   * @returns Result containing payment confirmation or error
   */
  processPayment(
    amount: number,
    currency: string,
    paymentMethodId: string
  ): Promise<Result<PaymentConfirmation, PaymentError>>;
}

export type PaymentConfirmation = {
  paymentId: string;
  status: 'succeeded' | 'failed' | 'pending';
  amount: number;
  currency: string;
  createdAt: Date;
};

export type PaymentError = 
  | { type: 'InsufficientFunds'; message: string }
  | { type: 'InvalidPaymentMethod'; message: string }
  | { type: 'ProcessingError'; message: string }
  | { type: 'GatewayError'; message: string };

// Application Layer - Use Case
// File: src/application/use-cases/ProcessPaymentUseCase.ts

import { IPaymentGateway } from '../../domain/ports/IPaymentGateway';

export class ProcessPaymentUseCase {
  constructor(private readonly paymentGateway: IPaymentGateway) {}

  async execute(
    amount: number,
    currency: string,
    paymentMethodId: string
  ): Promise<Result<PaymentConfirmation, PaymentError>> {
    // Validate inputs
    if (amount <= 0) {
      return Result.failure({ 
        type: 'ProcessingError', 
        message: 'Amount must be greater than zero' 
      });
    }

    if (!currency) {
      return Result.failure({ 
        type: 'ProcessingError', 
        message: 'Currency is required' 
      });
    }

    if (!paymentMethodId) {
      return Result.failure({ 
        type: 'ProcessingError', 
        message: 'Payment method ID is required' 
      });
    }

    // Delegate to the payment gateway
    return await this.paymentGateway.processPayment(
      amount,
      currency,
      paymentMethodId
    );
  }
}

// Infrastructure Layer - Adapter Implementation
// File: src/infrastructure/adapters/StripePaymentAdapter.ts

import { IPaymentGateway } from '../../domain/ports/IPaymentGateway';
import Stripe from 'stripe'; // This is acceptable in infrastructure layer

export class StripePaymentAdapter implements IPaymentGateway {
  private stripe: Stripe;

  constructor(stripeSecretKey: string) {
    this.stripe = new Stripe(stripeSecretKey, {
      apiVersion: '2023-10-16',
    });
  }

  async processPayment(
    amount: number,
    currency: string,
    paymentMethodId: string
  ): Promise<Result<PaymentConfirmation, PaymentError>> {
    try {
      // Create a payment intent
      const paymentIntent = await this.stripe.paymentIntents.create({
        amount,
        currency,
        payment_method: paymentMethodId,
        confirm: true,
        automatic_payment_methods: {
          enabled: false,
        },
      });

      // Map Stripe response to our domain type
      return Result.success({
        paymentId: paymentIntent.id,
        status: paymentIntent.status as 'succeeded' | 'failed' | 'pending',
        amount: paymentIntent.amount,
        currency: paymentIntent.currency,
        createdAt: new Date(paymentIntent.created * 1000),
      });
    } catch (error) {
      // Map Stripe errors to our domain errors
      if (error instanceof Stripe.errors.StripeError) {
        switch (error.type) {
          case 'card_error':
            return Result.failure({
              type: 'InvalidPaymentMethod',
              message: error.message,
            });
          case 'invalid_request_error':
            return Result.failure({
              type: 'ProcessingError',
              message: error.message,
            });
          case 'authentication_error':
          case 'rate_limit_error':
          case 'api_connection_error':
          case 'api_error':
            return Result.failure({
              type: 'GatewayError',
              message: 'Payment gateway error occurred',
            });
          default:
            return Result.failure({
              type: 'ProcessingError',
              message: 'An unexpected error occurred',
            });
        }
      }

      // Handle non-Stripe errors
      return Result.failure({
        type: 'GatewayError',
        message: 'Unexpected error occurred during payment processing',
      });
    }
  }
}

// Result Utility (Domain/Shared)
// File: src/domain/utils/Result.ts

export class Result<T, E> {
  private constructor(
    public readonly isSuccess: boolean,
    public readonly value?: T,
    public readonly error?: E
  ) {}

