// Domain/ValueObjects/Email.ts
import { Result, ok, err } from "../Result";
import { ValidationError } from "../Errors/ValidationError";

export class Email {
  private constructor(private readonly value: string) {
    // Private constructor to enforce creation through static factory method
  }

  /**
   * Creates a new Email value object with validation
   * @param email The email string to validate and normalize
   * @returns Result<Email, ValidationError> - Success with Email value object or error
   */
  static create(email: string): Result<Email, ValidationError> {
    // Check if email is empty or null
    if (!email || email.trim() === "") {
      return err(new ValidationError("Email cannot be empty"));
    }

    // Normalize to lowercase
    const normalizedEmail = email.toLowerCase().trim();

    // Validate email format using regex
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(normalizedEmail)) {
      return err(new ValidationError("Invalid email format"));
    }

    // Additional validation: ensure no consecutive dots
    if (normalizedEmail.includes("..")) {
      return err(new ValidationError("Email cannot contain consecutive dots"));
    }

    // Additional validation: ensure no leading/trailing dots
    if (normalizedEmail.startsWith(".") || normalizedEmail.endsWith(".")) {
      return err(new ValidationError("Email cannot start or end with a dot"));
    }

    return ok(new Email(normalizedEmail));
  }

  /**
   * Gets the normalized email value
   */
  getValue(): string {
    return this.value;
  }

  /**
   * Checks if two emails are equal
   */
  equals(other: Email): boolean {
    return this.value === other.value;
  }

  /**
   * Returns string representation of the email
   */
  toString(): string {
    return this.value;
  }
}

// Domain/Result.ts
export type Result<T, E> = Success<T> | Failure<E>;

class Success<T> {
  constructor(public readonly value: T) {}
  isSuccess = true as const;
  isFailure = false as const;
}

class Failure<E> {
  constructor(public readonly error: E) {}
  isSuccess = false as const;
  isFailure = true as const;
}

export function ok<T>(value: T): Result<T, never> {
  return new Success(value);
}

export function err<E>(error: E): Result<never, E> {
  return new Failure(error);
}
