    const validation = this.validateOrder(orderData);
    if (validation.isError()) {
      return error(validation.error);
    }

    // 2. Calculate tax
    const tax = orderData.total * 0.16;
    const orderWithTax = { ...orderData, tax };

    try {
      // 3. Save order
      const savedOrder = await this.orderRepository.save(orderWithTax);
      return ok(savedOrder);
    } catch (err) {
      // Handle repository errors
      return error(new ValidationError('Failed to save order'));
    }
  }

