I'll explain the problem with Active Record models that embed business rules in lifecycle hooks and show how to refactor them using Clean Architecture principles.

## The Problem: Active Record with Embedded Business Rules

Here's an example of problematic code where business logic is tightly coupled to the ORM model:

```ruby
# ❌ BAD: Business rules embedded in model
class Order < ActiveRecord::Base
  before_save :validate_and_set_discount

  validates :customer, presence: true
  validates :items, presence: true
  validates :total_amount, numericality: { greater_than: 0 }

  private

  def validate_and_set_discount
    # Business rule: Free shipping for orders over $100
    if total_amount >= 100
      self.shipping_cost = 0
    end

    # Business rule: Apply 10% discount for VIP customers
    if customer&.vip?
      self.discount_rate = 0.10
    end

    # Business rule: Maximum discount is 30%
    if discount_rate > 0.30
      self.discount_rate = 0.30
    end

    # Business rule: Order must have at least one item
    if items.empty?
      errors.add(:items, "must have at least one item")
      throw :abort
    end

    # Business rule: Total must be calculated correctly
    self.calculated_total = items.sum(&:price) - (items.sum(&:price) * discount_rate) + shipping_cost
  end
end
```

## The Refactoring: Clean Architecture Approach

### 1. Domain Layer (Pure Business Logic)

```typescript
// Domain/Entities/Order.ts
export class Order {
  private _id: string;
  private _customerId: string;
  private _items: OrderItem[];
  private _discountRate: number;
  private _shippingCost: number;
  private _status: OrderStatus;

  constructor(
    id: string,
    customerId: string,
    items: OrderItem[],
    discountRate: number = 0,
    shippingCost: number = 0,
    status: OrderStatus = OrderStatus.PENDING
  ) {
    this._id = id;
    this._customerId = customerId;
    this._items = items;
    this._discountRate = discountRate;
    this._shippingCost = shippingCost;
    this._status = status;
  }

  // Business rules as pure domain methods
  get totalAmount(): number {
    const subtotal = this._items.reduce((sum, item) => sum + item.price, 0);
    const discountAmount = subtotal * this._discountRate;
    return subtotal - discountAmount + this._shippingCost;
  }

  get itemCount(): number {
    return this._items.length;
  }

  // Pure domain validation
  validate(): Result<void, OrderValidationError> {
    if (!this._customerId) {
      return Result.failure(new OrderValidationError("Customer is required"));
    }

    if (this._items.length === 0) {
      return Result.failure(new OrderValidationError("Order must have at least one item"));
    }

    if (this._items.some(item => item.price <= 0)) {
      return Result.failure(new OrderValidationError("All items must have positive price"));
    }

    if (this._discountRate < 0 || this._discountRate > 0.30) {
      return Result.failure(new OrderValidationError("Discount rate must be between 0 and 30%"));
    }

    return Result.success(undefined);
  }

  // Business rule: Apply discounts based on customer type
  applyCustomerDiscount(customer: Customer): Order {
    if (customer.isVIP()) {
      return new Order(
        this._id,
        this._customerId,
        this._items,
        Math.min(0.30, this._discountRate + 0.10), // Max 30% discount
