import { Result, Ok, Err } from '../Types/Result';
import { Subscription } from '../../Domain/Entities/Subscription';
import { SubscriptionError, SubscriptionAlreadyExpiredError } from '../../Domain/Errors/SubscriptionErrors';

export interface CancelSubscriptionUseCase {
  execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionError>>;
}

export class CancelSubscriptionUseCaseImpl implements CancelSubscriptionUseCase {
  constructor(
    private readonly subscriptionRepository: SubscriptionRepository
  ) {}

  async execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionError>> {
    try {
      const subscription = await this.subscriptionRepository.findById(subscriptionId);

      if (!subscription) {
        return Err(new SubscriptionNotFoundError(subscriptionId));
      }

      const cancelledSubscription = subscription.cancel();

      await this.subscriptionRepository.save(cancelledSubscription);

      return Ok(cancelledSubscription);
    } catch (error) {
      if (error instanceof SubscriptionAlreadyExpiredError) {
        return Err(error);
      }
      return Err(new CancelSubscriptionFailedError());
    }
  }
}

