export interface ProcessPaymentRequest {
  amount: number;
  currency: string;
  paymentMethodId: string;
}

export interface ProcessPaymentResponse {
  transactionId: string;
  status: 'succeeded' | 'failed' | 'pending';
  amount: number;
  currency: string;
}

