  constructor(private readonly paymentGateway: IPaymentGateway) {}

  async execute(request: ProcessPaymentRequest): PaymentResult<ProcessPaymentResponse> {
    try {
      const result = await this.paymentGateway.processPayment(
        request.amount,
        request.currency,
        request.paymentMethodId
      );

      if (result.isErr()) {
        return Result.err(result.error);
      }

      const transaction = result.value;
      return Result.ok({
        transactionId: transaction.id,
        status: transaction.status,
        amount: transaction.amount,
        currency: transaction.currency
      });
    } catch (error) {
      return Result.err({
        code: 'PAYMENT_GATEWAY_ERROR',
        message: `Failed to process payment: ${error instanceof Error ? error.message : 'Unknown error'}`
      });
    }
  }
}

