  items: OrderItem[];
  total: number;
}

export interface ProcessOrderResponse {
  order: Order;
}

export class ProcessOrderUseCase {
  constructor(
    private readonly orderRepository: OrderRepository,
    private readonly taxCalculator: TaxCalculator,
    private readonly orderValidator: OrderValidator
  ) {}

  async execute(request: ProcessOrderRequest): Promise<Result<ProcessOrderResponse, OrderError>> {
    try {
      // Validate order
      const order: Order = {
        id: request.id,
        items: request.items,
        total: request.total,
        tax: 0,
        createdAt: new Date()
      };

      const validationError = await this.orderValidator.validate(order);
      if (validationError) {
        return error(validationError);
      }

      // Calculate tax
      order.tax = this.taxCalculator.calculateTax(order);

      // Save order
      const savedOrder = await this.orderRepository.save(order);

      return ok({ order: savedOrder });
    } catch (err) {
      return error(new OrderError(`Failed to process order: ${err instanceof Error ? err.message : 'Unknown error'}`));
    }
  }
}
