I'll explain the problem with Active Record models that embed business rules in lifecycle hooks and show how to refactor them using Clean Architecture principles.

## The Problem: Active Record with Embedded Business Rules

Here's an example of problematic Active Record code where business logic is tightly coupled to persistence:

```typescript
// ❌ BAD: Business rules embedded in ORM model
class User {
  private _email: string;
  private _age: number;
  private _status: 'active' | 'inactive' | 'suspended';

  constructor(email: string, age: number) {
    this._email = email;
    this._age = age;
    this._status = 'active';
  }

  // ❌ Business logic mixed with persistence
  beforeSave(): void {
    // Business rule: Must be 18+ to be active
    if (this._age < 18 && this._status === 'active') {
      throw new Error('Users must be 18+ to be active');
    }

    // Business rule: Email must be unique
    const existingUser = UserRepository.findByEmail(this._email);
    if (existingUser && existingUser.id !== this.id) {
      throw new Error('Email already exists');
    }

    // Business rule: Status can't be changed to suspended without approval
    if (this._status === 'suspended' && !this.hasApproval()) {
      throw new Error('Suspension requires approval');
    }
  }

  // ❌ Persistence concerns in domain model
  save(): void {
    this.beforeSave();
    // Database persistence logic here
    UserRepository.save(this);
  }
}
```

## The Solution: Clean Architecture Refactoring

### 1. Domain Layer (Pure Business Rules)

```typescript
// Domain Entities
interface UserEntity {
  id: string;
  email: string;
  age: number;
  status: UserStatus;
}

type UserStatus = 'active' | 'inactive' | 'suspended';

// Domain Errors
class UserError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'UserError';
  }
}

class InvalidAgeError extends UserError {
  constructor() {
    super('Users must be 18+ to be active');
  }
}

class DuplicateEmailError extends UserError {
  constructor() {
    super('Email already exists');
  }
}

class ApprovalRequiredError extends UserError {
  constructor() {
    super('Suspension requires approval');
  }
}

// Domain Business Rules
class UserBusinessRules {
  static validateAgeForStatus(age: number, status: UserStatus): Result<void, UserError> {
    if (age < 18 && status === 'active') {
      return Result.failure(new InvalidAgeError());
    }
    return Result.success(undefined);
  }

  static validateStatusChange(
    oldStatus: UserStatus, 
    newStatus: UserStatus,
    hasApproval: boolean
  ): Result<void, UserError> {
    if (oldStatus !== newStatus && newStatus === 'suspended' && !hasApproval) {
      return Result.failure(new ApprovalRequiredError());
    }
    return Result.success(undefined);
  }
}

// Domain Service for Complex Business Logic
class UserService {
  static validateUserCreation(
    email: string,
    age: number,
    userRepository: UserRepository
  ): Result<void, UserError> {
    // Validate age constraint
    const ageValidation = UserBusinessRules.validateAgeForStatus(age, 'active');
    if (ageValidation.isFailure()) {
      return ageValidation;
    }

    // Validate uniqueness constraint
    const existingUser = userRepository.findByEmail(email);
    if (existingUser) {
      return Result.failure(new DuplicateEmailError());
    }

    return Result.success(undefined);
  }

  static validateUserUpdate(
    user: UserEntity,
    newStatus: UserStatus,
    hasApproval: boolean,
    userRepository: UserRepository
  ): Result<void, UserError> {
    // Validate status change rules
    const statusValidation = UserBusinessRules.validateStatusChange(
      user.status,
      newStatus,
      hasApproval
    );
    if (statusValidation.isFailure()) {
      return statusValidation;
    }

    return Result.success(undefined);
  }
}
