// Domain/ValueObjects/Money.ts
export interface Money {
  readonly amount: number;
  readonly currency: string;
}

export class MoneyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "MoneyError";
  }
}

export class InvalidAmountError extends MoneyError {
  constructor() {
    super("Amount must be a positive number");
  }
}

export class InvalidCurrencyError extends MoneyError {
  constructor() {
    super("Currency must be a non-empty string");
  }
}

export class CurrencyMismatchError extends MoneyError {
  constructor() {
    super("Cannot add money with different currencies");
  }
}

export class MoneyValueObject {
  private constructor(private readonly value: Money) {
    // Private constructor to enforce creation through factory methods
  }

  public static create(amount: number, currency: string): Money {
    if (amount < 0 || !Number.isFinite(amount)) {
      throw new InvalidAmountError();
    }

    if (!currency || typeof currency !== 'string') {
      throw new InvalidCurrencyError();
    }

    return {
      amount,
      currency
    };
  }

  public static createFromMoney(money: Money): Money {
    return this.create(money.amount, money.currency);
  }

  public add(other: Money): Money {
    if (this.value.currency !== other.currency) {
      throw new CurrencyMismatchError();
    }

    const newAmount = this.value.amount + other.amount;

    return {
      amount: newAmount,
      currency: this.value.currency
    };
  }

  public get amount(): number {
    return this.value.amount;
  }

  public get currency(): string {
    return this.value.currency;
  }

  public equals(other: Money): boolean {
    return this.value.amount === other.amount && 
           this.value.currency === other.currency;
  }
}
```

This implementation provides:

1. **Pure Value Object**: The `MoneyValueObject` class encapsulates the `Money` value object with immutable properties
2. **Validation**: 
   - Ensures amount is positive and finite
   - Ensures currency is a non-empty string
3. **Currency Safety**: The `add` method validates that both money objects have the same currency
4. **Error Handling**: Custom error types for different failure cases
5. **Immutability**: All operations return new instances rather than modifying existing ones
6. **Type Safety**: Strict typing with interfaces and dedicated error types
7. **No External Dependencies**: Pure TypeScript with no framework or library dependencies

