// Domain Layer - Interfaces and Types
export interface IPaymentGateway {
  /**
   * Processes a payment transaction
   * @param paymentRequest - Payment details to process
   * @returns Result containing payment response or error
   */
  processPayment(paymentRequest: PaymentRequest): Promise<Result<PaymentResponse, PaymentError>>;
