  constructor(public readonly value: T) {}
  public isSuccess(): this is Ok<T> {
    return true;
  }
  public isFailure(): this is Err<DomainError> {
    return false;
  }
}

export class Err<E extends DomainError> {
  constructor(public readonly error: E) {}
  public isSuccess(): this is Ok<unknown> {
    return false;
  }
  public isFailure(): this is Err<DomainError> {
    return true;
  }
}
