// src/domain/services/UserValidationService.ts
export class UserValidationService {
  static validateAge(age: number): Result<void, UserAgeError> {
    if (age < 18) {
      return Result.failure(new UserAgeError('User must be at least 18 years old'));
    }
    return Result.success(undefined);
  }

  static validateEmailUniqueness(
    email: string,
    userRepository: UserRepository
  ): Promise<Result<void, UserEmailError>> {
    return userRepository.findByEmail(email).then(existingUser => {
      if (existingUser) {
        return Result.failure(new UserEmailError('Email already exists'));
      }
      return Result.success(undefined);
    });
  }

  static validateStatus(status: string): Result<void, UserStatusError> {
    const validStatuses: Array<'active' | 'inactive' | 'suspended'> = ['active', 'inactive', 'suspended'];
    if (!validStatuses.includes(status as any)) {
      return Result.failure(new UserStatusError('Invalid status'));
    }
    return Result.success(undefined);
  }

  static validateUser(user: User, userRepository: UserRepository): Promise<Result<void, Error>> {
    const ageValidation = this.validateAge(user.age);
    if (ageValidation.isFailure()) {
      return Promise.resolve(ageValidation);
    }

    const statusValidation = this.validateStatus(user.status);
    if (statusValidation.isFailure()) {
      return Promise.resolve(statusValidation);
    }

    return this.validateEmailUniqueness(user.email, userRepository);
  }
}

