```typescript
// application/usecases/ProcessOrderUseCaseImpl.ts
import { Result, ok, error } from '../../shared/utils/Result';
import { ProcessOrderUseCase } from './ProcessOrderUseCase';
import { Order, OrderData } from '../../domain/models/Order';
import { OrderError, InvalidOrderError, OrderValidationError } from '../../domain/errors/OrderError';
import { OrderRepository } from '../../domain/repositories/OrderRepository';
import { TaxCalculator } from '../../domain/services/TaxCalculator';

export class ProcessOrderUseCaseImpl implements ProcessOrderUseCase {
  constructor(
    private readonly orderRepository: OrderRepository,
    private readonly taxCalculator: TaxCalculator
  ) {}

  async execute(orderData: OrderData): Promise<Result<Order, OrderError>> {
    // Validate order data
    const validation = this.validateOrder(orderData);
    if (validation.isError()) {
      return error(validation.error);
    }

    // Calculate tax
    const tax = this.taxCalculator.calculateTax(orderData);

    // Create order entity
    const order: Order = {
      ...orderData,
      tax,
      createdAt: new Date()
    };

    // Save order
    try {
      await this.orderRepository.save(order);
      return ok(order);
    } catch (err) {
      return error(new OrderError('Failed to save order'));
    }
  }

  private validateOrder(orderData: OrderData): Result<void, OrderValidationError> {
    if (!orderData.items || orderData.items.length === 0) {
      return error(new OrderValidationError('Order must have at least one item'));
    }

    if (orderData.total < 0) {
      return error(new OrderValidationError('Order total cannot be negative'));
    }

    return ok(undefined);
  }
}
```

